def table(head,rows,cls=''):
 return '<div class="tablewrap '+cls+'"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def sec(key,num,title,lead=''):
 return f'<section class="section" id="{key}"><div class="sectionhead"><div class="number">{num+1:02}</div><h2>{title}</h2>'+('<p class="lead">'+lead+'</p>' if lead else '')+'</div>'
B=[]
B.append('''<div class="eyebrow">产品比较与设计建议 · 合并阅读版</div><h1>Loop、Multica、MobileWork：<br>怎么用、差在哪，Work应该怎么做？</h1><p class="lead">先看融合后的 Work：用任务看板组织团队工作，在任意任务下像话题一样沟通、@同事和智能体；团队管理、设置和自动化贯穿其中。再对照三个产品，判断哪些可借鉴、哪些需补齐。</p><div class="take"><b>先给结论</b><p>融合方向是一个<b>人和智能体共同工作的团队空间</b>：重点做好任务看板、任务下的话题沟通和@、团队管理，以及团队与智能体设置；现有定时任务接入看板和话题。团队聊天目前没有，后续再做。</p></div>''')
B.append(sec('difference',1,'先看懂：三个产品分别在帮助用户做什么'))
B.append('''<div class="cards"><article class="card"><div class="pname">平凯 Loop</div><h3>从团队讨论出发</h3><div class="quote">“我们正在一起推进什么？”</div><p>先在频道里对齐事情，复杂问题单独开话题，再把需要跟进的内容变成任务。AI是讨论和任务的参与者。</p><div class="fit"><b>最值得借鉴</b><p>讨论有主线、有分支；做完后把进展和成果带回原来的讨论。</p></div></article><article class="card"><div class="pname">Multica</div><h3>从一件任务出发</h3><div class="quote">“这件事归谁，现在到哪一步？”</div><p>先把目标变成可跟踪任务，放进项目；评论、分派、AI处理、返工和完成记录都围绕这件任务积累。</p><div class="fit"><b>最值得借鉴</b><p>任务持续存在，AI可以做很多轮；责任、执行、成果和完成状态分开看。</p></div></article><article class="card"><div class="pname">MobileWork</div><h3>从个人工作台出发</h3><div class="quote">“帮我在当前环境里把事情做好。”</div><p>选择工作空间和专家，发出需求，AI调用工具、操作浏览器、产生文件，用户在任务里继续追问和检查成果。</p><div class="fit"><b>最值得保留</b><p>个人执行体验：专家好调用，浏览器能接管，成果文件容易查看。</p></div></article></div>''')
