 colors=['#6b55c9','#2563c9','#0d8a76','#b63767','#b96b25','#5e7188']
 for i,(t,a,b) in enumerate(m['branches']):
  y=20+i*114;cy=y+46;c=colors[i]
  out.append(f'<path d="M242 352 H270 V{cy} H310" stroke="{c}" stroke-opacity=".6" stroke-width="1.6" fill="none"/><rect x="310" y="{y}" width="745" height="94" rx="10" fill="#fafaf8" stroke="#e0dfd7"/><rect x="310" y="{y}" width="5" height="94" rx="2" fill="{c}"/><text x="334" y="{y+29}" font-size="18" font-weight="600" fill="{c}">{t}</text><text x="334" y="{y+55}" font-size="14" fill="#4e5968">{a}</text><text x="334" y="{y+77}" font-size="14" fill="#4e5968">{b}</text>')
 out.append(f'<rect x="18" y="294" width="224" height="116" rx="12" fill="#f1edfc" stroke="#6b55c9"/><text x="130" y="327" text-anchor="middle" font-size="18" fill="#6b55c9">{m["product"]}</text><text x="130" y="355" text-anchor="middle" font-size="19" font-weight="600" fill="#1c2330">{m["root"]}</text><text x="130" y="383" text-anchor="middle" font-size="12" fill="#626c77">{m["sub"]}</text></svg>')
