def sequence_svg(s):
 n=len(s['events']);width=1000;height=140+n*88;xs=[115,375,635,885]
 out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" role="img" aria-label="{esc(s["title"])}"><rect width="100%" height="100%" fill="white"/><defs><marker id="a-{s["key"]}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#2563c9"/></marker></defs>']
 for i,(x,name) in enumerate(zip(xs,LANES)):
  out.append(f'<rect x="{x-107}" y="15" width="214" height="46" rx="7" fill="{["#f1edfc","#eaf1fd","#fbeaf0","#e6f5f1"][i]}"/><text x="{x}" y="44" text-anchor="middle" font-size="14" font-weight="600" fill="#1c2330">{name}</text><path d="M{x} 65V{height-25}" stroke="#bdc6d0" stroke-dasharray="4 5"/>')
 for i,(a,b,t,note) in enumerate(s['events']):
  y=104+i*88;xa,xb=xs[a],xs[b];mid=(xa+xb)/2
  out.append(f'<g><rect x="6" y="{y-27}" width="988" height="79" rx="5" fill="{["#f6f8fa","#fff"][i%2]}" fill-opacity=".7"/><text x="14" y="{y+3}" font-size="12" fill="#75818f">{i+1:02}</text>')
  if a==b:
   out.append(f'<path d="M{xa} {y}h110v18h-110" stroke="#2563c9" fill="none" marker-end="url(#a-{s["key"]})"/>');mid=xa+100
  else:out.append(f'<path d="M{xa} {y}H{xb}" stroke="#2563c9" stroke-width="1.8" marker-end="url(#a-{s["key"]})"/>')
  # 每个动作的名称靠近自己的箭头，解释置于下方整行。
  tw=max(100,len(t)*14)
  out.append(f'<rect x="{mid-tw/2-5}" y="{y-25}" width="{tw+10}" height="22" rx="3" fill="white"/><text x="{mid}" y="{y-9}" text-anchor="middle" font-size="14" fill="#1c2330">{t}</text><text x="500" y="{y+36}" text-anchor="middle" font-size="13" fill="#626c77">{note}</text><circle cx="{xa}" cy="{y}" r="3" fill="#6b55c9"/></g>')
 return ''.join(out)+'</svg>'
